// ── Rate Limiting ─────────────────────────────────────────────────────────────
const globalLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 200, message: { success: false, message: 'Too many requests, please try again after 15 minutes.' }, standardHeaders: true, legacyHeaders: false });
const scopeLimiter  = rateLimit({ windowMs: 60 * 1000, max: 20, message: { success: false, message: 'Scope generation limit reached. Try again in 1 minute.' } });
const authLimiter   = rateLimit({ windowMs: 15 * 60 * 1000, max: 10, message: { success: false, message: 'Too many login attempts. Try again in 15 minutes.' } });

app.use(globalLimiter);

// ── Auth Middleware ───────────────────────────────────────────────────────────
function authRequired(req, res, next) {
  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) return res.status(401).json({ success: false, message: 'Authentication required' });
  try {
    req.contractor = jwt.verify(header.slice(7), JWT_SECRET);
    next();
  } catch (e) {
    return res.status(401).json({ success: false, message: 'Invalid or expired token' });
  }
}

