// Health
app.get('/api/health', (req,res) => res.json({ status:'ok', service:'Build-IQ API', version:'3.0.0', db: supabase ? 'supabase' : 'in-memory', uptime:Math.floor(process.uptime())+'s', timestamp:new Date().toISOString() }));

// API Docs
app.get('/api', (req,res) => res.json({ service:'Build-IQ REST API v3.0', endpoints:{ health:'GET /api/health', auth:{ register:'POST /api/auth/register', login:'POST /api/auth/login', me:'GET /api/auth/me (protected)' }, products:'GET /api/products', scope:'POST /api/scope/generate (rate limited)', orders:{ place:'POST /api/orders', list:'GET /api/orders', single:'GET /api/orders/:id' }}}));

// ── AUTH ──────────────────────────────────────────────────────────────────────
app.post('/api/auth/register', authLimiter, async (req,res) => {
  const { name, email, phone, city, password } = req.body;
  if (!name||!email||!password) return res.status(400).json({ success:false, message:'Name, email and password are required' });
  if (password.length < 6) return res.status(400).json({ success:false, message:'Password must be at least 6 characters' });

  try {
    const hash = await bcrypt.hash(password, 12);
    const contractor = { id: uuidv4(), name, email: email.toLowerCase(), phone:phone||'', city:city||'', password_hash:hash, created_at: new Date().toISOString() };

    if (supabase) {
      const existing = await supabase.from('contractors').select('id').eq('email', email.toLowerCase()).single();
      if (existing.data) return res.status(409).json({ success:false, message:'Email already registered' });
      const { error } = await supabase.from('contractors').insert([contractor]);
      if (error) throw error;
    } else {
      if (_contractors.find(c => c.email === email.toLowerCase())) return res.status(409).json({ success:false, message:'Email already registered' });
      _contractors.push(contractor);
    }

    const token = jwt.sign({ id:contractor.id, name:contractor.name, email:contractor.email }, JWT_SECRET, { expiresIn:'7d' });
    res.status(201).json({ success:true, message:'Contractor registered successfully!', token, contractor:{ id:contractor.id, name:contractor.name, email:contractor.email, city:contractor.city }});
  } catch(e) {
    console.error(e);
    res.status(500).json({ success:false, message:'Registration failed', error:e.message });
  }
});

app.post('/api/auth/login', authLimiter, async (req,res) => {
  const { email, password } = req.body;
  if (!email||!password) return res.status(400).json({ success:false, message:'Email and password are required' });

  try {
    let contractor;
    if (supabase) {
      const { data, error } = await supabase.from('contractors').select('*').eq('email', email.toLowerCase()).single();
      if (error || !data) return res.status(401).json({ success:false, message:'Invalid email or password' });
      contractor = data;
    } else {
      contractor = _contractors.find(c => c.email === email.toLowerCase());
      if (!contractor) return res.status(401).json({ success:false, message:'Invalid email or password' });
    }

    const valid = await bcrypt.compare(password, contractor.password_hash);
    if (!valid) return res.status(401).json({ success:false, message:'Invalid email or password' });

    const token = jwt.sign({ id:contractor.id, name:contractor.name, email:contractor.email }, JWT_SECRET, { expiresIn:'7d' });
    res.json({ success:true, message:'Login successful!', token, contractor:{ id:contractor.id, name:contractor.name, email:contractor.email, city:contractor.city }});
  } catch(e) {
    res.status(500).json({ success:false, message:'Login failed', error:e.message });
  }
});

app.get('/api/auth/me', authRequired, (req,res) => {
  res.json({ success:true, contractor: req.contractor });
});

// ── PRODUCTS ──────────────────────────────────────────────────────────────────
app.get('/api/products', (req,res) => {
  let products = [...PRODUCTS];
  const { category, search, sort } = req.query;
  if (category && category !== 'all') products = products.filter(p => p.category === category);
  if (search) { const q=search.toLowerCase(); products=products.filter(p=>p.name.toLowerCase().includes(q)||p.tags.some(t=>t.includes(q))); }
  if (sort==='price_asc') products.sort((a,b)=>a.price-b.price);
  if (sort==='price_desc') products.sort((a,b)=>b.price-a.price);
  if (sort==='discount') products.sort((a,b)=>b.discount-a.discount);
  res.json({ success:true, count:products.length, products });
});

app.get('/api/products/meta/categories', (req,res) => {
  const categories=[...new Set(PRODUCTS.map(p=>p.category))];
  const counts={};
  categories.forEach(c=>{counts[c]=PRODUCTS.filter(p=>p.category===c).length;});
  res.json({ success:true, categories, counts });
});

app.get('/api/products/:id', (req,res) => {
  const product=PRODUCTS.find(p=>p.id===req.params.id);
  if (!product) return res.status(404).json({ success:false, message:'Product not found' });
  res.json({ success:true, product });
});

// ── SCOPE ─────────────────────────────────────────────────────────────────────
app.post('/api/scope/generate', scopeLimiter, (req,res) => {
  const { description } = req.body;
  if (!description||!description.trim()) return res.status(400).json({ success:false, message:'Description is required' });
  const lower=description.toLowerCase();
  let scope={ type:'general', ...SCOPE_RULES.general };
  for (const [type,rule] of Object.entries(SCOPE_RULES)) {
    if (type==='general') continue;
    if (rule.keywords.some(kw=>lower.includes(kw))) { scope={type,...rule}; break; }
  }
  const materialTotal=scope.boq.reduce((sum,item)=>sum+item.price,0);
  res.json({ success:true, input:description, scope:{ type:scope.type, trades:scope.trades, duration:scope.duration, confidence:scope.confidence, laborCost:scope.laborCost, materialCost:materialTotal, grandTotal:scope.laborCost+materialTotal, boq:scope.boq.map((item,i)=>({id:'boq-'+(i+1),...item,checked:true})), generatedAt:new Date().toISOString(), engine:'Build-IQ AI Engine v3.0' }});
});

// ── ORDERS ────────────────────────────────────────────────────────────────────
app.post('/api/orders', async (req,res) => {
  const { items, contactName, contactPhone, city, notes } = req.body;
  if (!items||!Array.isArray(items)||items.length===0) return res.status(400).json({ success:false, message:'Cart is empty' });
  const total=items.reduce((sum,item)=>sum+(item.price*(item.qty||1)),0);
  const order={ id:'ORD-'+uuidv4().split('-')[0].toUpperCase(), status:'confirmed', items, total, contactName:contactName||'Anonymous', contactPhone:contactPhone||'', city:city||'Not specified', notes:notes||'', created_at:new Date().toISOString(), estimatedDispatch:new Date(Date.now()+2*24*60*60*1000).toISOString() };
  try {
    if (supabase) {
      const { error } = await supabase.from('orders').insert([order]);
      if (error) throw error;
    } else {
      _orders.push(order);
    }
    res.status(201).json({ success:true, message:'Order '+order.id+' confirmed! Dispatch in 2 business days.', order });
  } catch(e) {
    res.status(500).json({ success:false, message:'Order failed', error:e.message });
  }
});

app.get('/api/orders', async (req,res) => {
  try {
    if (supabase) {
      const { data, error } = await supabase.from('orders').select('*').order('created_at', { ascending:false });
      if (error) throw error;
      return res.json({ success:true, count:data.length, orders:data });
    }
    res.json({ success:true, count:_orders.length, orders:_orders });
  } catch(e) {
    res.status(500).json({ success:false, message:'Failed to fetch orders' });
  }
});

app.get('/api/orders/:id', async (req,res) => {
  try {
    if (supabase) {
      const { data, error } = await supabase.from('orders').select('*').eq('id', req.params.id).single();
      if (error || !data) return res.status(404).json({ success:false, message:'Order not found' });
      return res.json({ success:true, order:data });
    }
    const order=_orders.find(o=>o.id===req.params.id);
    if (!order) return res.status(404).json({ success:false, message:'Order not found' });
    res.json({ success:true, order });
  } catch(e) {
    res.status(500).json({ success:false, message:'Failed to fetch order' });
  }
});

// ── Frontend ──────────────────────────────────────────────────────────────────
app.get('*', (req,res) => res.send(HTML));

// ── Start (local only) ────────────────────────────────────────────────────────
if (!process.env.VERCEL) {
  app.listen(PORT, () => console.log('Build-IQ running at http://localhost:' + PORT));
}

module.exports = app;
